+
+    function validateField(fieldName) {
+      const field = fields[fieldName];
+      const message = field.validate(field.input.value);
+      setFieldError(field, message);
+      return message;
+    }
+
+    function clearStatus() {
+      statusMessage.hidden = true;
+      statusMessage.textContent = "";
+    }
+
+    Object.keys(fields).forEach((fieldName) => {
+      const field = fields[fieldName];
+
+      field.input.addEventListener("blur", () => {
+        validateField(fieldName);
+      });
+
+      field.input.addEventListener("input", () => {
+        if (!field.error.hidden) {
+          validateField(fieldName);
+        }
+        clearStatus();
+      });
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+      clearStatus();
+
+      const invalidFields = Object.keys(fields).filter((fieldName) => validateField(fieldName));
+
+      if (invalidFields.length > 0) {
+        fields[invalidFields[0]].input.focus();
+        return;
+      }
+
+      statusMessage.textContent = "Your support request is ready to be sent.";
+      statusMessage.hidden = false;
+      form.reset();
+
+      Object.values(fields).forEach((field) => {
+        setFieldError(field, "");
+      });
+    });
