      padding: 1rem;
      border: 1px solid #ffffff2e;
      border-radius: var(--radius-md);
      background: #ffffff12;
    }

    .hero-points strong {
      display: block;
      margin-bottom: 0.35rem;
      font-size: 0.98rem;
    }

    .hero-points span {
      color: #eef3ff;
      font-size: 0.92rem;
      line-height: 1.5;
    }

    .form-card {
      padding: 2rem;
      border: 1px solid #d6ddec;
      border-radius: var(--radius-lg);
      background: var(--panel-bg);
      box-shadow: var(--shadow);
    }

    .form-card h2 {
      margin: 0 0 0.5rem;
      font-size: 1.45rem;
    }

    .form-intro {
      margin: 0 0 1.5rem;
      color: var(--text-secondary);
      line-height: 1.6;
    }

