      display: grid;
      gap: 1rem;
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    .form-label-row {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      align-items: baseline;
    }

    label {
      font-weight: 600;
    }

    .required-indicator {
      color: var(--danger);
      font-weight: 700;
    }

    .field-meta {
      color: var(--text-secondary);
      font-size: 0.87rem;
    }

    input {
      width: 100%;
      min-height: 3.25rem;
      padding: 0.9rem 1rem;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      background: var(--panel-muted);
      color: var(--text-primary);
      transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
    }

    input::placeholder {
      color: #6d7890;
    }

    input:hover {
      border-color: var(--border-strong);
      background: #ffffff;
    }

    input:focus {
      outline: 2px solid transparent;
      border-color: var(--accent);
      background: #ffffff;
      box-shadow: 0 0 0 4px #3158d333;
    }

    .helper-text,
    .error-message,
    .form-status {
      font-size: 0.92rem;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--text-secondary);
    }

    .error-message {
      color: var(--danger);
    }

    .error-message[hidden],
    .form-status[hidden] {
      display: none;
    }

    .form-field.has-error input {
      border-color: var(--danger);
      background: #fff7f6;
    }

    .form-status {
      padding: 0.9rem 1rem;
      border-radius: var(--radius-sm);
      border: 1px solid #b7dfc6;
      background: #edf9f1;
      color: var(--success);
    }

    .submit-button {
      display: inline-flex;
      justify-content: center;
      align-items: center;
      min-height: 3.5rem;
      padding: 0.95rem 1.25rem;
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #ffffff;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.15s ease, box-shadow 0.2s ease;
      box-shadow: 0 16px 28px -18px #3158d3cc;
    }

    .submit-button:hover {
      transform: translateY(-1px);
    }

    .submit-button:focus-visible {
      outline: 2px solid transparent;
      box-shadow: 0 0 0 4px #3158d34d;
    }

    .submit-button:active {
      transform: translateY(0);
    }

    @media (max-width: 820px) {
      .page-shell {
        width: min(100% - 1rem, 1080px);
        padding-top: 1rem;
      }

      .page-header {
        flex-direction: column;
        align-items: flex-start;
        margin-bottom: 1.5rem;
      }

      .hero {
        grid-template-columns: 1fr;
