<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <div class="page-shell">
    <header class="page-header">
      <div class="brand">Aster Support</div>
      <p class="header-note">Product help for onboarding, account access, and customer support.</p>
    </header>

    <main id="main-content">
      <section class="hero" aria-labelledby="support-heading">
        <div class="hero-copy">
          <span class="eyebrow">Support page</span>
          <h1 id="support-heading">Get expert help from our support team.</h1>
          <p>
            Share a few details and we&apos;ll route your request to the right specialist. Required
            fields are marked clearly, and phone number is optional if email is your preferred contact method.
          </p>
          <div class="hero-points" aria-label="Support highlights">
            <div>
              <strong>Fast handoff</strong>
              <span>Send the essentials so our team can follow up quickly.</span>
            </div>
            <div>
              <strong>Flexible contact</strong>
              <span>Use email only, or add a phone number for a call back.</span>
            </div>
          </div>
        </div>

        <div class="form-card">
          <h2>Contact support</h2>
          <p class="form-intro">Complete the form below and submit your request.</p>

          <form id="support-form" novalidate>
            <div class="form-field">
              <div class="form-label-row">
                <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
                <span class="field-meta">Required</span>
              </div>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-required="true"
                aria-describedby="full-name-error"
                placeholder="Jordan Lee"
              >
              <div id="full-name-error" class="error-message" hidden></div>
            </div>

            <div class="form-field">
              <div class="form-label-row">
                <label for="email-address">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
                <span class="field-meta">Required</span>
              </div>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                inputmode="email"
                required
                aria-required="true"
                aria-describedby="email-address-error"
                placeholder="you@company.com"
              >
              <div id="email-address-error" class="error-message" hidden></div>
            </div>

            <div class="form-field">
              <div class="form-label-row">
                <label for="phone-number">Phone number</label>
                <span class="field-meta">Optional</span>
              </div>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                autocomplete="tel"
                inputmode="tel"
                aria-describedby="phone-number-help phone-number-error"
                placeholder="+1 555 123 4567"
              >
              <div id="phone-number-help" class="helper-text">
                Expected format: use digits with an optional country code, for example +1 555 123 4567.
              </div>
              <div id="phone-number-error" class="error-message" hidden></div>
            </div>

            <div id="form-status" class="form-status" aria-live="polite" hidden></div>

            <button class="submit-button" type="submit">Submit request</button>
          </form>
        </div>
      </section>
    </main>
  </div>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");

    const fields = {
      fullName: {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Enter your full name.";
          }
          return "";
        }
      },
      email: {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        validate(value) {
          if (!value.trim()) {
            return "Enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Enter a valid email address.";
          }
          return "";
        }
      },
      phone: {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        validate(value) {
          const trimmedValue = value.trim();
          if (!trimmedValue) {
            return "";
          }

          const phonePattern = /^\+?[0-9()\s-]{7,20}$/;
          if (!phonePattern.test(trimmedValue)) {
            return "Enter a valid phone number using digits, spaces, dashes, or parentheses.";
          }
          return "";
        }
      }
    };

    function setFieldError(field, message) {
      const wrapper = field.input.closest(".form-field");
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
      field.error.textContent = message;
      field.error.hidden = !message;
      wrapper.classList.toggle("has-error", Boolean(message));
    }

    function validateField(fieldName) {
      const field = fields[fieldName];
      const message = field.validate(field.input.value);
      setFieldError(field, message);
      return message;
    }

    function clearStatus() {
      statusMessage.hidden = true;
      statusMessage.textContent = "";
    }

    Object.keys(fields).forEach((fieldName) => {
      const field = fields[fieldName];

      field.input.addEventListener("blur", () => {
        validateField(fieldName);
      });

      field.input.addEventListener("input", () => {
        if (!field.error.hidden) {
          validateField(fieldName);
        }
        clearStatus();
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      clearStatus();

      const invalidFields = Object.keys(fields).filter((fieldName) => validateField(fieldName));

      if (invalidFields.length > 0) {
        fields[invalidFields[0]].input.focus();
        return;
      }

      statusMessage.textContent = "Your support request is ready to be sent.";
      statusMessage.hidden = false;
      form.reset();

      Object.values(fields).forEach((field) => {
        setFieldError(field, "");
      });
    });
  </script>
</body>
</html>
